import os, csv, math, datetime as dt
from collections import defaultdict

BASE_DIRS = [
    'storage/shared/agents/kairos/VEN/threshold_sweep',
    'storage/kairos/VEN/threshold_sweep',
    'storage/shared/agents/zephyr/threshold_sweep',
]

# Field aliases tailored to ven_threshold_sweep.csv + related files
FIELD_ALIASES = {
    'dist': ['dist','distribution','dataset','name','label'],
    'threshold': ['threshold_frac','threshold','thr','t','alpha'],
    'y': ['ridge_points','ridge_points_mean','max_ven','max_ven_mean',
          'ridge_extent','extent','score','synergy_index','stability_index'],
    'tail_mass': ['tail_mass','tail','tailmass'],
    'emergence': ['emergence','E','emerg','emergence_index'],
}

EXTRA_TAIL_FILES = [
    'tail_sensitivity_slopes_all.csv',
    'tail_sensitivity_slopes.csv',
]

OUT_DIR = 'storage/shared/agents/kairos/VEN/v3'
os.makedirs(OUT_DIR, exist_ok=True)

def sniff_csv(path):
    with open(path, 'r', encoding='utf-8', newline='') as f:
        head = f.read(4096)
        f.seek(0)
        try:
            dialect = csv.Sniffer().sniff(head, delimiters=',;\t|')
        except Exception:
            dialect = csv.excel
        return list(csv.DictReader(f, dialect=dialect))

def find_key(row, keys):
    for k in row.keys():
        if k is None: 
            continue
        kk = k.strip().lower()
        for tgt in keys:
            if kk == tgt:
                return k
    return None

def to_float(x):
    try:
        if x is None or x == '':
            return None
        return float(x)
    except Exception:
        return None

def gaussian_weight(t, c, E, sigma_base=0.05):
    e = 0.0 if E is None else max(0.0, min(1.0, float(E)))
    sigma = max(1e-6, min(0.25, sigma_base * (1.0 + e)))
    return math.exp(-((t - c) ** 2) / (2.0 * sigma * sigma)) * (1.0 if E is None else e)

def weighted_slope(xs, ys, ws):
    sw = sum(ws)
    if sw <= 0:
        return None
    xw = sum(w*x for w,x in zip(ws,xs)) / sw
    yw = sum(w*y for w,y in zip(ws,ys)) / sw
    num = sum(w*(x-xw)*(y-yw) for w,x,y in zip(ws,xs,ys))
    den = sum(w*(x-xw)*(x-xw) for w,x in zip(ws,xs))
    return None if den <= 0 else num/den

def dedup_by_t(points):
    buckets = defaultdict(list)
    for p in points:
        buckets[round(p['t'], 6)].append(p)
    out = []
    for k, lst in buckets.items():
        y_vals = [p['y'] for p in lst if p['y'] is not None]
        E_vals = [p['E'] for p in lst if p['E'] is not None]
        tail_vals = [p['tail'] for p in lst if p['tail'] is not None]
        y = sum(y_vals)/len(y_vals) if y_vals else None
        E = sum(E_vals)/len(E_vals) if E_vals else None
        tail = sum(tail_vals)/len(tail_vals) if tail_vals else None
        out.append({'t': k, 'y': y, 'E': E, 'tail': tail})
    out.sort(key=lambda d: d['t'])
    return out

def load_tail_mass_map():
    tm = {}
    for b in BASE_DIRS:
        if not os.path.exists(b):
            continue
        for fn in EXTRA_TAIL_FILES:
            p = os.path.join(b, fn)
            if not os.path.exists(p):
                continue
            try:
                rows = sniff_csv(p)
            except Exception:
                continue
            for r in rows:
                dkey = find_key(r, FIELD_ALIASES['dist'])
                tkey = find_key(r, FIELD_ALIASES['tail_mass'])
                if not dkey or not tkey:
                    continue
                dist = r[dkey].strip()
                tail = to_float(r.get(tkey))
                if dist and tail is not None:
                    tm[dist] = tail
    return tm

def gather_points():
    groups = defaultdict(list)
    files_used = []
    for base in BASE_DIRS:
        if not os.path.exists(base):
            continue
        for root, _, fns in os.walk(base):
            for fn in fns:
                if not fn.lower().endswith('.csv'):
                    continue
                p = os.path.join(root, fn)
                try:
                    rows = sniff_csv(p)
                except Exception:
                    continue
                # Only use threshold sweep-like CSVs here
                if 'threshold' not in fn.lower() and 'sweep' not in fn.lower() and 'ven_threshold' not in fn.lower():
                    continue
                files_used.append(p)
                for r in rows:
                    dkey = find_key(r, FIELD_ALIASES['dist'])
                    tkey = find_key(r, FIELD_ALIASES['threshold'])
                    ykey = find_key(r, FIELD_ALIASES['y'])
                    Ekey = find_key(r, FIELD_ALIASES['emergence'])
                    dist = (r.get(dkey).strip() if dkey else os.path.basename(root))
                    t = to_float(r.get(tkey)) if tkey else None
                    y = to_float(r.get(ykey)) if ykey else None
                    E = to_float(r.get(Ekey)) if Ekey else None
                    if dist and (t is not None) and (y is not None):
                        groups[dist].append({'t': t, 'y': y, 'E': E, 'tail': None})
    # Dedup and sort
    for d in list(groups.keys()):
        pts = [p for p in groups[d] if p['t'] is not None and p['y'] is not None]
        if len(pts) < 4:
            groups.pop(d, None)
        else:
            groups[d] = dedup_by_t(pts)
    return groups, files_used

def dynamic_c_grid(ts, step=None):
    # Use midpoints between sorted unique thresholds; ensures left/right points exist
    ts = sorted(set(ts))
    mids = [(a+b)/2.0 for a, b in zip(ts[:-1], ts[1:])]
    return mids

def compute_flip(groups):
    results = []
    for dist, pts in groups.items():
        tvals = [p['t'] for p in pts]
        cg = dynamic_c_grid(tvals)
        best = None
        for c in cg:
            left = [p for p in pts if p['t'] < c]
            right = [p for p in pts if p['t'] >= c]
            if len(left) < 2 or len(right) < 2:
                continue
            wl = [gaussian_weight(p['t'], c, p['E']) for p in left]
            wr = [gaussian_weight(p['t'], c, p['E']) for p in right]
            sl = weighted_slope([p['t'] for p in left], [p['y'] for p in left], wl)
            sr = weighted_slope([p['t'] for p in right], [p['y'] for p in right], wr)
            if sl is None or sr is None:
                continue
            diff = sr - sl
            obj = abs(diff) * (sum(wl)+sum(wr))
            if (best is None) or (obj > best['obj']):
                best = {'c': c, 'k2A': sl, 'k2B': sr, 'diff': diff, 'obj': obj}
        if best:
            results.append({'dist': dist, 'c_star': best['c'], 'k2A': best['k2A'], 'k2B': best['k2B'], 'flip_diff': best['diff']})
    return results

def attach_tail_mass(metrics, tail_map):
    for m in metrics:
        m['tail_mass'] = tail_map.get(m['dist'])
    return metrics

def main():
    groups, files_used = gather_points()
    tail_map = load_tail_mass_map()
    metrics = compute_flip(groups)
    metrics = attach_tail_mass(metrics, tail_map)

    # Aggregates
    if metrics:
        c_vals = [m['c_star'] for m in metrics]
        diffs = [m['flip_diff'] for m in metrics]
        k2A_vals = [m['k2A'] for m in metrics]
        k2B_vals = [m['k2B'] for m in metrics]
        c_global = sum(c_vals)/len(c_vals)
        diff_mean = sum(diffs)/len(diffs)
        k2A_mean = sum(k2A_vals)/len(k2A_vals)
        k2B_mean = sum(k2B_vals)/len(k2B_vals)
    else:
        c_global = diff_mean = k2A_mean = k2B_mean = None

    # Save
    csv_path = os.path.join(OUT_DIR, 'v3_flip_metrics.csv')
    with open(csv_path, 'w', encoding='utf-8', newline='') as f:
        cols = ['dist','tail_mass','c_star','k2A','k2B','flip_diff']
        w = csv.DictWriter(f, fieldnames=cols)
        w.writeheader()
        for m in metrics:
            w.writerow(m)

    summary_path = os.path.join(OUT_DIR, 'v3_summary.txt')
    with open(summary_path, 'w', encoding='utf-8') as f:
        f.write("VEN v3c Gaussian-weighted hinge (dynamic c-grid + schema aliases)\n")
        f.write(f"timestamp: {dt.datetime.utcnow().isoformat()}Z\n")
        f.write("files_used:\n")
        for p in files_used:
            f.write(f"  - {p}\n")
        f.write(f"n_dists: {len(metrics)}\n")
        f.write(f"c_global≈{c_global}\n")
        f.write(f"k2A_mean≈{k2A_mean}, k2B_mean≈{k2B_mean}, diff_mean≈{diff_mean}\n")
        for m in metrics:
            dn = m['dist'].lower()
            if '0.7' in dn or '07_08' in dn:
                f.write(f"note: anomaly_probe dist={m['dist']} c*={m['c_star']} k2A={m['k2A']} k2B={m['k2B']} diff={m['flip_diff']}\n")

    print(f"[v3c] dists={len(metrics)} c_global={c_global}")
    print(f"[v3c] means: k2A={k2A_mean}, k2B={k2B_mean}, diff={diff_mean}")
    print(f"[artifacts] {csv_path} | {summary_path}")

if __name__ == "__main__":
    main()
